import { Group } from '@visx/group';
import React from 'react';

import { WithId } from '../../../types/with-id.js';
import { MarkerAtom } from '../../annotations-atoms/components/MarkerAtom.js';
import { TestIds } from '../constants.js';
import { defineMarkerColor } from '../functions/define-marker-color.js';
import { defineMarkerContent } from '../functions/define-marker-content.js';
import { getMarkerProps } from '../functions/get-marker-props.js';
import { useAnnotationsRenderer } from '../hooks/useAnnotationsRenderer.js';
import { useMarkersBrightnessState } from '../hooks/useMarkersBrightnessState.js';
import { AnnotationData } from '../types/annotations.js';
import { CircleMarkerProps, PillMarkerProps } from '../types/markers.js';

export interface MarkerRendererProps {
  data: WithId<AnnotationData>[];
  markerId: string;
  onMarkerHover: (itemId: string) => void;
  trackNumber: number;
}

export const MarkerRenderer = ({
  data,
  markerId,
  onMarkerHover,
  trackNumber,
}: MarkerRendererProps) => {
  const { scale } = useAnnotationsRenderer();

  const [markerData] = data;

  const color = defineMarkerColor(data);

  const state = useMarkersBrightnessState(markerId, trackNumber, data);

  const { x, width } = getMarkerProps(markerData, scale);

  const markerProps: PillMarkerProps | CircleMarkerProps = {
    x,
    data,
    color,
    width,
  };

  const markerContent = defineMarkerContent(data);

  return (
    <Group data-testid={`${TestIds.Marker}-${markerId}`}>
      <MarkerAtom
        x={markerProps.x}
        width={markerProps.width}
        color={markerProps.color}
        onMouseEnter={() => {
          onMarkerHover(markerId);
        }}
        content={markerContent}
        interactionState={state}
      />
    </Group>
  );
};

MarkerRenderer['displayName'] = 'MarkerRenderer';
